# collector to read events generated by Suricata eve.json log

import json
import time
from pathlib import Path
from typing import Any

EVE_LOG = Path("/var/log/suricata/eve.json")

# first version focused on useful network events
SELECTED_EVENT_TYPES = {"alert", "dns", "flow"}


# print selected Suricata event in readable format
def display_event(event: dict[str, Any]) -> None:
    event_type = event.get("event_type", "unknown type")
    timestamp = event.get("timestamp", "unknown time")
    src_ip = event.get("src_ip", "-")
    dest_ip = event.get("dest_ip", "-")

    if event_type == "alert":
        alert = event.get("alert", {})

        print(
            f"[ALERT]   {timestamp} | "
            f"{src_ip} -> {dest_ip} | "
            f"signature= {alert.get('signature', 'unknown')} | "
            f"severity= {alert.get('severity', 'unknown')}"
        )
    elif event_type == "dns":
        dns = event.get("dns", {})
        query = dns.get("rrname", "unknown")
        print(f"[DNS]   {timestamp} | {src_ip} -> {dest_ip} | query= {query}")

    elif event_type == "flow":
        proto = event.get("proto", "unknown")
        dest_port = event.get("dest_port", "unknown")

        print(
            f"[FLOW]    {timestamp} | "
            f"{src_ip} -> {dest_ip}:{dest_port} | "
            f"protocol= {proto}"
        )


# follow new lines in eve.json and display selected events
def follow_eve_log(path: Path = EVE_LOG) -> None:
    print("LookoutIDS collector starting...")
    print(f"Reading Suricata log: {path}")
    print("Waiting for new events... Press Ctrl+C to stop.\n")

    # open in text mode and process only new events
    with path.open("r", encoding="utf-8") as log_file:
        log_file.seek(0, 2)  # reading pos to end of file

        while True:
            line = log_file.readline()

            if not line:
                time.sleep(0.2)
                continue

            try:
                event = json.loads(line)
            except json.JSONDecodeError:
                continue  # bad line should not break collector

            if event.get("event_type") in SELECTED_EVENT_TYPES:
                display_event(event)


def main() -> None:
    # start collector
    if not EVE_LOG.is_file():
        raise FileNotFoundError(f"Suricata EVE log not found: {EVE_LOG}")

    try:
        follow_eve_log()
    except KeyboardInterrupt:
        print("\nLookoutIDS collector stopped.")


if __name__ == "__main__":
    main()
